import { test, expect } from '@playwright/test';

test('user can add a todo item', async ({ page }) => {
  await page.goto('https://demo.playwright.dev/todomvc');

  // getByPlaceholder — finds by placeholder text (accessible)
  const todoInput = page.getByPlaceholder('What needs to be done?');
  await todoInput.fill('Write Playwright tests');
  await todoInput.press('Enter');

  // getByText — finds by visible text content
  const todoItem = page.getByText('Write Playwright tests');
  await expect(todoItem).toBeVisible();
});

