// Coming in Unit 3 — assertions that auto-retry
import { test, expect } from '@playwright/test';

test('todo count updates after adding items', async ({ page }) => {
  await page.goto('https://demo.playwright.dev/todomvc');

  const input = page.getByPlaceholder('What needs to be done?');
  await input.fill('First task');
  await input.press('Enter');
  await input.fill('Second task');
  await input.press('Enter');

  // This auto-retries until count equals 2 or times out
  await expect(page.getByTestId('todo-count')).toHaveText('2 items left');
});
